const u16=(data,offset,value)=>new DataView(data.buffer,data.byteOffset,data.byteLength).setUint16(offset,value,true);
const u32=(data,offset,value)=>new DataView(data.buffer,data.byteOffset,data.byteLength).setUint32(offset,value>>>0,true);
