export function xlsxPage(state,columns,rows){const data=bytes(rows.map((row,i)=>xlsxRow(columns.map(c=>row[c.key]),state.row+i+5)).join(''));return {data,state:{...state,row:state.row+rows.length,zipOffset:state.zipOffset+data.length,sheetSize:state.sheetSize+data.length,crc:crcUpdate(state.crc,data)}};}
